def is_valid_credit_card(card_number):
    # Luhn algorithm
    digits = [int(d) for d in str(card_number) if d.isdigit()]

    if len(digits) < 13 or len(digits) > 19:
        return False

    checksum = 0
    for i, digit in enumerate(reversed(digits)):
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        checksum += digit

    return checksum % 10 == 0
