def paginate_api(url, per_page=100):
    page = 1
    while True:
        response = requests.get(url, params={'page': page, 'per_page': per_page})
        response.raise_for_status()
        data = response.json()

        if not data:
            break

        yield from data
        page += 1

# Or with cursor-based pagination
def paginate_cursor(url, cursor=None):
    while True:
        params = {}
        if cursor:
            params['cursor'] = cursor

        response = requests.get(url, params=params)
        data = response.json()

        yield from data['items']

        if not data.get('next_cursor'):
            break

        cursor = data['next_cursor']

for item in paginate_api('https://api.example.com/users'):
