import json

def memoize_with_kwargs(func):
    cache = {}

    @wraps(func)
    def wrapper(*args, **kwargs):
        # Create cache key from args and kwargs
        key = json.dumps({
            'args': args,
            'kwargs': sorted(kwargs.items())
        }, default=str, sort_keys=True)

        if key not in cache:
            cache[key] = func(*args, **kwargs)

        return cache[key]

